import{_ as t,o as a,c as i,ak as n}from"./chunks/framework.B8jO0odJ.js";const p=JSON.parse('{"title":"Chainy Trello / GitHub sync","description":"Status: LIVE as of October 5, 2026. The user explicitly approved credential storage in the connected Cloudflare account. Both webhooks are active, and all 26 existing tasks ar","frontmatter":{"title":"Chainy Trello / GitHub sync","description":"Status: LIVE as of October 5, 2026. The user explicitly approved credential storage in the connected Cloudflare account. Both webhooks are active, and all 26 existing tasks ar","source":"tools/kanban-sync/README.md","category":"Guides & tooling","sourceUpdated":"2026-10-08T06:33:54+08:00","outline":[2,3]},"headers":[],"relativePath":"content/tools/kanban-sync/readme.md","filePath":"content/tools/kanban-sync/readme.md"}'),s={name:"content/tools/kanban-sync/readme.md"};function r(o,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<div><h1 id="chainy-trello--github-sync">Chainy Trello / GitHub sync<a class="header-anchor" href="#chainy-trello--github-sync" aria-label="Link to this section">​</a></h1><p>Status: LIVE as of October 5, 2026. The user explicitly approved credential storage in the connected Cloudflare account. Both webhooks are active, and all 26 existing tasks are linked. Final status: zero queued jobs and zero failures. No new GitHub issues were created.</p><p>Endpoints: GitHub organization Project 5 and Trello CAPSTONE T13 (VPH0LHFN). Service: <a href="https://chainy-kanban-sync.hainy.workers.dev">https://chainy-kanban-sync.hainy.workers.dev</a>. Non-secret IDs are recorded in board-map.json.</p><h2 id="behavior">Behavior<a class="header-anchor" href="#behavior" aria-label="Link to this section">​</a></h2><ul><li>Existing GitHub issues are linked to Trello cards by a stable issue-URL marker; no new GitHub issues are created.</li><li>Todo / In Progress / Done map to the GitHub Project Status field. Issue open/closed state is not modified by a card move.</li><li>Titles and descriptions synchronize in both directions; the description&#39;s existing Status line follows the Project status. Named Lead/Support/Reviewer and acceptance evidence remain in the issue/card text; there are no invented GitHub accounts.</li><li>Three-way field merging preserves independent edits. Simultaneous same-field conflict: GitHub wins; a conflict event is logged. Do not remove the managed link marker at the bottom of a card.</li><li>New comments are copied with author attribution and an explicit sync marker. Comment edits/deletions and old pre-link comments are not mirrored. The sending identity is the integration&#39;s connected account, not an impersonation of the original author.</li><li>Signed Trello/GitHub webhooks enqueue persistent jobs in a SQLite Durable Object scoped to the board. Jobs retry with capped exponential backoff. Duplicate delivery is ignored; ambiguous comment POST outcomes are checked against destination markers before retry.</li><li>A 15-minute reconciliation schedule repairs missed field updates and discovers new comments missed by webhooks. Live sample observations were 6.8 seconds Trello to GitHub and 2.8 seconds GitHub to Trello; these are individual results, not a latency guarantee.</li><li>Archived/moved cards and unknown statuses stop that task&#39;s sync and appear in authenticated status diagnostics. Unlinked new cards are ignored. New project issues require an explicit re-run of the import. Attachments, separate Trello checklists, member assignments and custom Project metadata do not have independent bidirectional mappings.</li></ul><h2 id="setup-and-activation">Setup and activation<a class="header-anchor" href="#setup-and-activation" aria-label="Link to this section">​</a></h2><ol><li>Set-TrelloCredentials.ps1 stores API key, read/write token and application secret as Windows-user DPAPI-encrypted values in %LOCALAPPDATA%/ChainyIntegration/trello.credentials.xml. No secrets belong in this repository. The token generated using the supplied 30-day URL needs renewal before the November 21, 2026 pre-final.</li><li>GitHub CLI must have repo/project access and admin:org_hook for organization webhook setup. Cloudflare Wrangler must be authenticated. Both account checks and the GitHub scope refresh succeeded on October 5, 2026.</li><li>Obtain the user&#39;s explicit approval before uploading the actual Trello credentials and current GitHub CLI token to Cloudflare. Auto-review initially rejected the transfer; the user subsequently explicitly approved all listed secrets and the Cloudflare destination. The current CLI token is broader than this board; prefer a dedicated GitHub App/token for longer-term operation. Code limits writes to linked issues in Chainy and Chainy-Game and Project 5.</li><li>After approval, create random ADMIN_TOKEN and WEBHOOK_SECRET, retain their encrypted copies outside the repository, and upload those plus TRELLO_KEY, TRELLO_TOKEN, TRELLO_SECRET, GITHUB_TOKEN and PUBLIC_URL using Wrangler secret bulk via stdin. Never echo values or put them in command arguments. The approved upload completed; secret values are not stored here.</li><li>Run Initialize-Board.ps1 without -Apply to inspect. Then -Apply -Limit 1 creates/reuses the three lists and first linked card. Registration validates board, issue and project IDs. A rerun reuses matching marker cards; duplicate or archived matches block import.</li><li>Register exactly one Trello board webhook at /webhooks/trello. Register an organization GitHub webhook at /webhooks/github for issues, issue_comment and projects_v2_item, signed with WEBHOOK_SECRET. List existing hooks before creating either. GitHub Projects webhook availability is public preview; verify actual delivery payloads.</li><li>Change SYNC_ENABLED to true in wrangler.jsonc and deploy. Verify a real task move and a reversible title/description edit in both directions, signature rejection, duplicate delivery and queued recovery. Measure latency. Do not mark acceptance work Done as part of tests.</li><li>Once the live test passes, run Initialize-Board.ps1 -Apply -Limit 100 for all current issues. Verify 26 distinct mappings/cards against the actual live inventory. Record verified outcomes in board-map.json and the project baseline. Do not claim all steps passed based on local tests.</li></ol><h2 id="development--checks">Development / checks<a class="header-anchor" href="#development--checks" aria-label="Link to this section">​</a></h2><p>From this directory: npm ci; npx wrangler types; npm run check; npm test. The test pre-step creates a dry-run bundle in ignored dist/. npm test uses dummy credentials and mocked APIs inside the real local Cloudflare runtime. Ten tests passed October 5, 2026, including both update directions, duplicate delivery, invalid signatures, simulated temporary GitHub failure/retry and comments in both directions. Type checking and Wrangler dry-run also passed. PowerShell helper/import syntax checks passed; import dry-run found an empty Trello board and selected CH-01.</p><p>Live verification passed October 5: titles, descriptions, statuses and new comments in both directions; original task content/status restored; temporary test comments removed; unsigned Trello/GitHub requests rejected with 401; GitHub Project delivery replay accepted with no extra tasks or outstanding jobs. All 26 card titles, descriptions, lists and issue links match the live project. Recovery from a simulated GitHub outage was verified locally. The Trello token expires November 4, 2026 and must be renewed before then.</p><h2 id="operations">Operations<a class="header-anchor" href="#operations" aria-label="Link to this section">​</a></h2><ul><li>GET /health exposes only the service name. GET /admin/status requires ADMIN_TOKEN and reports enabled state, linked count, queued jobs and sanitized failure codes. POST /admin/reconcile requests repair. Keep the admin token private.</li><li>Disable by setting SYNC_ENABLED=false and deploying; pending jobs remain durable. Remove/deactivate external webhooks for a full shutdown. Do not delete storage during an outage.</li><li>Rotate secrets with Wrangler; update GitHub webhook signing secret together with WEBHOOK_SECRET. Re-register Trello webhooks if the bound token is revoked. Refresh GITHUB_TOKEN if the corresponding CLI grant is revoked or rotated.</li><li>Keep the service on free-tier resources; no paid plan changes are authorized. Check actual usage once activated. A 26-task board is a sizing assumption, not proof of a free-tier performance guarantee.</li><li>Protect the November 21 pre-final: this is management tooling and must not consume the reserved game integration, device QA, manuscript or rehearsal buffer.</li></ul><h2 id="trello-card-presentation">Trello card presentation<a class="header-anchor" href="#trello-card-presentation" aria-label="Link to this section">​</a></h2><p>User requested dates, member-name labels/assignments, and acceptance checklists on every linked card. Format-Board.ps1 reads the live GitHub Project target dates and leads, reuses or creates one colored label per named lead, sets each due date to 23:59 Asia/Manila on the existing target date, optionally assigns matching board members only with -AssignMembers, and creates native Acceptance checklist items from the issue&#39;s Acceptance section. It does not invent start dates, invite people, remove other labels/members, reset existing checklist ticks, or duplicate matching checklist items. Run without -Apply to inspect; use -Apply to update. Unknown or ambiguous lead names block changes.</p><p>The native checklist and date/member/label decorations are Trello-local. The webhook service preserves them but does not synchronize their independent edits back to GitHub. Original Acceptance Markdown remains in the shared description to preserve the issue&#39;s acceptance evidence. Existing proposal dates retain their meaning; setting a Trello due date does not make them adviser-approved deadlines. The user chose name labels only for now. New members can later be assigned by rerunning Format-Board.ps1 -Apply -AssignMembers after they join the board. Checking every acceptance box is not automatic proof of task completion; linked evidence and reviewer verification are still required.</p></div>',1)])])}const m=t(s,[["render",r]]);export{p as __pageData,m as default};
